{
  "name": "Inteligentní PDF Databáze",
  "description": "Jednoduchá databáze, která automaticky extrahuje data z nahraných PDF souborů pomocí Gemini AI a ukládá je do prohlížeče."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ExtractedData {
  title: string;
  summary: string;
  date: string;
  category: string;
  tags: string[];
  entityNames: string[];
}

export interface DocumentRecord {
  id: string;
  fileName: string;
  uploadDate: string;
  data: ExtractedData;
  rawBase64?: string; // Storing for preview if needed, keeping it simple for now
}

export enum AppView {
  DASHBOARD = 'DASHBOARD',
  UPLOAD = 'UPLOAD',
  DETAIL = 'DETAIL'
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ExtractedData } from "../types";

const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

const analysisSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    title: {
      type: Type.STRING,
      description: "Hlavní nadpis nebo název dokumentu.",
    },
    summary: {
      type: Type.STRING,
      description: "Stručné shrnutí obsahu dokumentu v českém jazyce (max 2 věty).",
    },
    date: {
      type: Type.STRING,
      description: "Datum uvedené v dokumentu (např. datum faktury, datum vydání) ve formátu RRRR-MM-DD. Pokud není nalezeno, použij dnešní.",
    },
    category: {
      type: Type.STRING,
      description: "Kategorie dokumentu (např. Faktura, Smlouva, Článek, Rozpočet, Ostatní).",
    },
    tags: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Klíčová slova popisující dokument.",
    },
    entityNames: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Jména důležitých osob nebo organizací zmíněných v dokumentu.",
    }
  },
  required: ["title", "summary", "category", "tags"],
};

export const analyzePdfDocument = async (base64Pdf: string): Promise<ExtractedData> => {
  if (!apiKey) {
    throw new Error("API Key is missing. Please check your configuration.");
  }

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "application/pdf",
              data: base64Pdf,
            },
          },
          {
            text: "Analyzuj tento PDF dokument a extrahuj strukturovaná data podle schématu. Odpovídej pouze v Češtině.",
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: analysisSchema,
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response text received from Gemini.");
    }

    const data = JSON.parse(text) as ExtractedData;
    return data;
  } catch (error) {
    console.error("Error analyzing PDF:", error);
    throw error;
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  className = '', 
  disabled,
  ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center px-4 py-2 rounded-lg font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500",
    secondary: "bg-white text-gray-700 border border-gray-300 hover:bg-gray-50 focus:ring-blue-500",
    danger: "bg-red-600 text-white hover:bg-red-700 focus:ring-red-500",
    ghost: "bg-transparent text-gray-600 hover:bg-gray-100 focus:ring-gray-500"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={disabled || isLoading}
      {...props}
    >
      {isLoading ? (
        <span className="flex items-center space-x-2">
          <svg className="animate-spin h-4 w-4 text-current" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
          </svg>
          <span>Zpracovávám...</span>
        </span>
      ) : children}
    </button>
  );
};

import React, { useState, useRef } from 'react';
import { Upload, FileText, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Button } from './Button';
import { analyzePdfDocument } from '../services/geminiService';
import { DocumentRecord } from '../types';
import { v4 as uuidv4 } from 'uuid';

interface ScannerProps {
  onScanComplete: (doc: DocumentRecord) => void;
  onCancel: () => void;
}

export const Scanner: React.FC<ScannerProps> = ({ onScanComplete, onCancel }) => {
  const [file, setFile] = useState<File | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    setError(null);
    if (selectedFile) {
      if (selectedFile.type !== 'application/pdf') {
        setError("Prosím vyberte pouze PDF soubor.");
        return;
      }
      setFile(selectedFile);
    }
  };

  const convertFileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => {
        const result = reader.result as string;
        // Remove the data URL prefix (e.g., "data:application/pdf;base64,")
        const base64 = result.split(',')[1];
        resolve(base64);
      };
      reader.onerror = error => reject(error);
    });
  };

  const handleScan = async () => {
    if (!file) return;

    setIsScanning(true);
    setError(null);

    try {
      const base64Data = await convertFileToBase64(file);
      const extractedData = await analyzePdfDocument(base64Data);

      const newRecord: DocumentRecord = {
        id: uuidv4(),
        fileName: file.name,
        uploadDate: new Date().toISOString(),
        data: extractedData,
      };

      onScanComplete(newRecord);
    } catch (err: any) {
      setError(err.message || "Nastala chyba při analýze dokumentu. Zkuste to prosím znovu.");
    } finally {
      setIsScanning(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto p-6 bg-white rounded-xl shadow-sm border border-slate-200">
      <div className="text-center mb-8">
        <div className="mx-auto h-12 w-12 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-4">
          <Upload size={24} />
        </div>
        <h2 className="text-2xl font-bold text-slate-800">Nahrát nový dokument</h2>
        <p className="text-slate-500 mt-2">Vyberte PDF soubor pro automatickou analýzu a extrakci dat.</p>
      </div>

      <div className="mb-6">
        <div 
          onClick={() => fileInputRef.current?.click()}
          className={`border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-colors ${
            file ? 'border-blue-500 bg-blue-50' : 'border-slate-300 hover:border-slate-400 hover:bg-slate-50'
          }`}
        >
          <input 
            type="file" 
            ref={fileInputRef}
            onChange={handleFileChange}
            accept="application/pdf"
            className="hidden" 
          />

          {file ? (
            <div className="flex flex-col items-center">
              <FileText size={48} className="text-blue-500 mb-2" />
              <p className="font-medium text-slate-800">{file.name}</p>
              <p className="text-sm text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
              <p className="text-xs text-blue-600 mt-2 font-medium">Klikněte pro změnu</p>
            </div>
          ) : (
            <div className="flex flex-col items-center">
              <Upload size={48} className="text-slate-300 mb-2" />
              <p className="font-medium text-slate-700">Klikněte pro výběr souboru</p>
              <p className="text-sm text-slate-400">Pouze PDF soubory</p>
            </div>
          )}
        </div>

        {error && (
          <div className="mt-4 p-4 bg-red-50 text-red-700 rounded-lg flex items-start gap-3">
            <AlertCircle size={20} className="mt-0.5 flex-shrink-0" />
            <p className="text-sm">{error}</p>
          </div>
        )}
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t border-slate-100">
        <Button variant="secondary" onClick={onCancel} disabled={isScanning}>
          Zrušit
        </Button>
        <Button onClick={handleScan} disabled={!file} isLoading={isScanning}>
          Analyzovat a Uložit
        </Button>
      </div>
    </div>
  );
};

import React from 'react';
import { DocumentRecord } from '../types';
import { FileText, Calendar, Tag, Trash2, Search, Plus } from 'lucide-react';
import { Button } from './Button';

interface DashboardProps {
  documents: DocumentRecord[];
  onAddClick: () => void;
  onDeleteClick: (id: string) => void;
  onViewClick: (doc: DocumentRecord) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ documents, onAddClick, onDeleteClick, onViewClick }) => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [categoryFilter, setCategoryFilter] = React.useState<string>('all');

  const categories = Array.from(new Set(documents.map(d => d.data.category))).filter(Boolean);

  const filteredDocs = documents.filter(doc => {
    const matchesSearch = doc.data.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          doc.data.summary.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = categoryFilter === 'all' || doc.data.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="space-y-6">
      {/* Header Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Celkem dokumentů</p>
          <p className="text-3xl font-bold text-slate-800">{documents.length}</p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Poslední přidání</p>
          <p className="text-3xl font-bold text-slate-800">
            {documents.length > 0 
              ? new Date(documents[0].uploadDate).toLocaleDateString('cs-CZ') 
              : '-'}
          </p>
        </div>
        <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 flex flex-col items-start justify-center">
          <Button onClick={onAddClick} className="w-full h-full text-lg">
            <Plus className="mr-2" size={20} />
            Přidat dokument
          </Button>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col md:flex-row gap-4 justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-200">
        <div className="relative w-full md:w-96">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Hledat v dokumentech..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none"
          />
        </div>
        <div className="flex gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
          <button 
            onClick={() => setCategoryFilter('all')}
            className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap ${categoryFilter === 'all' ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
          >
            Vše
          </button>
          {categories.map(cat => (
             <button 
             key={cat}
             onClick={() => setCategoryFilter(cat)}
             className={`px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap ${categoryFilter === cat ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
           >
             {cat}
           </button>
          ))}
        </div>
      </div>

      {/* List */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredDocs.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <FileText size={48} className="mx-auto mb-4 text-slate-300" />
            <p className="text-lg">Žádné dokumenty nenalezeny</p>
            {documents.length === 0 && <p className="text-sm mt-2">Začněte nahráním prvního PDF.</p>}
          </div>
        ) : (
          <div className="divide-y divide-slate-100">
            {filteredDocs.map((doc) => (
              <div key={doc.id} className="p-6 hover:bg-slate-50 transition-colors group">
                <div className="flex flex-col md:flex-row md:items-start justify-between gap-4">
                  <div className="flex-1 cursor-pointer" onClick={() => onViewClick(doc)}>
                    <div className="flex items-center gap-2 mb-2">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-100 text-blue-800">
                        {doc.data.category}
                      </span>
                      <span className="text-xs text-slate-400 flex items-center">
                        <Calendar size={12} className="mr-1" />
                        {new Date(doc.data.date).toLocaleDateString('cs-CZ')}
                      </span>
                    </div>
                    <h3 className="text-lg font-semibold text-slate-900 mb-1 group-hover:text-blue-600 transition-colors">
                      {doc.data.title}
                    </h3>
                    <p className="text-slate-600 text-sm line-clamp-2 mb-3">
                      {doc.data.summary}
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {doc.data.tags.slice(0, 4).map((tag, idx) => (
                        <span key={idx} className="inline-flex items-center text-xs text-slate-500 bg-slate-100 px-2 py-1 rounded">
                          <Tag size={10} className="mr-1" />
                          {tag}
                        </span>
                      ))}
                    </div>
                  </div>
                  <div className="flex items-center gap-2 md:self-center">
                    <Button variant="ghost" className="text-red-500 hover:text-red-700 hover:bg-red-50" onClick={() => onDeleteClick(doc.id)}>
                      <Trash2 size={18} />
                    </Button>
                    <Button variant="secondary" onClick={() => onViewClick(doc)}>
                      Detail
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

