import React, { useMemo } from 'react';
import { DocumentRecord, AnnualTargets, RowStatus } from '../types';
import { Ruler, TrendingUp, AlertCircle, CheckCircle2, PieChart, Wrench, Ban, Clock } from 'lucide-react';

interface StatisticsPanelProps {
  documents: DocumentRecord[];
  targets: AnnualTargets;
  yearFilter: string; // 'all' or specific year like '2023'
  monthFilter: string; // 'all' or '1'-'12'
  mergeDuplicates: boolean;
}

// Re-use helper functions logic
const findDateColumnIndex = (headers: string[]): number => {
    if (!headers) return -1;
    const lowerHeaders = headers.map(h => h.toLowerCase());
    return lowerHeaders.findIndex(h => 
        h.includes('datum') || h.includes('dne') || h.includes('kdy') || h.includes('termín') || h.includes('date')
    );
};

const findLengthColumnIndex = (headers: string[]): number => {
    if (!headers) return -1;
    const lowerHeaders = headers.map(h => h.toLowerCase());
    return lowerHeaders.findIndex(h => 
        h.includes('délka') || h.includes('delka') || h.includes('metr') || h.includes('metráž') || h.includes('length') || h === 'm'
    );
};

const parseLengthValue = (str: string | undefined): number => {
    if (!str) return 0;
    const normalized = str.replace(',', '.');
    const match = normalized.match(/[\d.]+/);
    if (!match) return 0;
    const val = parseFloat(match[0]);
    return isNaN(val) ? 0 : val;
};

const MONTH_NAMES_SHORT = ["Led", "Úno", "Bře", "Dub", "Kvě", "Čvn", "Čvc", "Srp", "Zář", "Říj", "Lis", "Pro"];

export const StatisticsPanel: React.FC<StatisticsPanelProps> = ({ 
  documents, 
  targets, 
  yearFilter, 
  monthFilter,
  mergeDuplicates 
}) => {

  const { data, statusCounts } = useMemo(() => {
    // 1. Prepare data structure: Center -> Month -> Meters
    const data: Record<string, Record<number, number>> = {};
    const statusCounts: Record<string, { total: number, uploaded: number, gisIssues: number }> = {}; 
    const seenSignatures = new Set<string>();

    // Init centers
    const allCenters = new Set<string>([...Object.keys(targets), ...documents.map(d => d.data.center)]);
    allCenters.forEach(c => {
        if (!c || c === 'Neurčeno') return;
        data[c] = {};
        for(let m=1; m<=12; m++) data[c][m] = 0;

        statusCounts[c] = {
            total: 0,
            uploaded: 0,
            gisIssues: 0
        };
    });

    documents.forEach(doc => {
        const center = doc.data.center;
        if (!center || center === 'Neurčeno') return;

        const dateColIdx = findDateColumnIndex(doc.data.tableHeaders);
        const lenColIdx = findLengthColumnIndex(doc.data.tableHeaders);

        doc.data.tableRows.forEach((row, idx) => {
            // Smart Merge Check
            const signature = [center, ...row.values.map(v => v?.trim().toLowerCase())].join('|');
            if (mergeDuplicates) {
                if (seenSignatures.has(signature)) return;
                seenSignatures.add(signature);
            }

            // Parse Date
            let month = 0;
            let year = 0;

            // Try row date first
            if (dateColIdx >= 0 && row.values[dateColIdx]) {
                const d = new Date(row.values[dateColIdx]);
                if (!isNaN(d.getTime())) {
                    month = d.getMonth() + 1;
                    year = d.getFullYear();
                }
            } 

            // Fallback to document date
            if (month === 0) {
                 const d = new Date(doc.data.date);
                 if (!isNaN(d.getTime())) {
                    month = d.getMonth() + 1;
                    year = d.getFullYear();
                 }
            }

            // Apply Year Filter
            if (yearFilter !== 'all' && year.toString() !== yearFilter) return;
            // Apply Month Filter (Only for status counts to match view context)
             if (monthFilter !== 'all' && month.toString() !== monthFilter) return;

            // --- METERS CALCULATION (Only if length column exists) ---
            if (lenColIdx >= 0) {
                const meters = parseLengthValue(row.values[lenColIdx]);
                if (!data[center]) {
                    data[center] = {};
                    for(let m=1; m<=12; m++) data[center][m] = 0;
                }
                data[center][month] = (data[center][month] || 0) + meters;
            }

            // --- STATUS & QUALITY COUNTING ---
            if (statusCounts[center]) {
                statusCounts[center].total++;
                if (row.status === RowStatus.UPLOADED) {
                    statusCounts[center].uploaded++;
                }
                if (row.requiresGisFix) {
                    statusCounts[center].gisIssues++;
                }
            }
        });
    });

    return { data, statusCounts };
  }, [documents, targets, yearFilter, monthFilter, mergeDuplicates]);

  const activeCenters = Object.keys(data).sort();

  // Helper to get plan
  // Logic Changed: targets[center] is now ANNUAL target
  const getFilteredPlanTotal = (center: string) => {
     const annualTarget = targets[center] || 0;

     // If looking at a specific month, the plan is roughly annual / 12
     if (monthFilter !== 'all') {
         return annualTarget / 12;
     }

     // If looking at "all" months (year view), return the full annual target
     return annualTarget;
  };

  const getFilteredActualTotal = (center: string) => {
    if (monthFilter !== 'all') {
        return data[center][parseInt(monthFilter)] || 0;
    }
    // Sum all months
    return Object.values(data[center]).reduce((a: number, b: number) => a + b, 0);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-300">

      {/* 1. SECTION: Center Overview (Cards) */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
            <Ruler className="mr-2 text-blue-600" size={20} />
            Přehled plnění plánu podle středisek
            {yearFilter !== 'all' && <span className="ml-2 text-slate-400 font-normal">({yearFilter})</span>}
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {activeCenters.map(center => {
                const plan = getFilteredPlanTotal(center);
                const actual = getFilteredActualTotal(center);
                const percent = plan > 0 ? (actual / plan) * 100 : 0;
                const isSuccess = percent >= 100;

                return (
                    <div key={center} className="bg-slate-50 rounded-lg p-4 border border-slate-200 hover:border-blue-300 transition-colors">
                        <div className="flex justify-between items-start mb-2">
                            <h4 className="font-bold text-slate-700">{center}</h4>
                            <span className={`text-xs font-bold px-2 py-1 rounded-full ${isSuccess ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-200 text-slate-600'}`}>
                                {percent.toFixed(0)} %
                            </span>
                        </div>

                        <div className="space-y-1 mb-3">
                            <div className="flex justify-between text-sm">
                                <span className="text-slate-500">Realita:</span>
                                <span className="font-semibold text-slate-900">{actual.toLocaleString('cs-CZ', { maximumFractionDigits: 0 })} m</span>
                            </div>
                            <div className="flex justify-between text-sm">
                                <span className="text-slate-500">Plán ({monthFilter === 'all' ? 'rok' : 'měsíc'}):</span>
                                <span className="font-medium text-slate-600">{plan.toLocaleString('cs-CZ', { maximumFractionDigits: 0 })} m</span>
                            </div>
                        </div>

                        {/* Progress Bar */}
                        <div className="w-full bg-slate-200 rounded-full h-2.5 overflow-hidden">
                            <div 
                                className={`h-2.5 rounded-full ${isSuccess ? 'bg-emerald-500' : (percent < 50 ? 'bg-red-500' : 'bg-amber-500')}`} 
                                style={{ width: `${Math.min(percent, 100)}%` }}
                            ></div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

       {/* 2. SECTION: Quality & Status Statistics (NEW) */}
       <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
         <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
            <PieChart className="mr-2 text-blue-600" size={20} />
            Kvalita dat a stavy
        </h3>
        <div className="overflow-x-auto">
             <table className="min-w-full text-sm">
                <thead>
                    <tr className="bg-slate-50 text-slate-500 border-b border-slate-200">
                        <th className="p-3 text-left font-semibold">Středisko</th>
                        <th className="p-3 text-right font-semibold">Celkem záznamů</th>
                        <th className="p-3 text-right font-semibold text-emerald-600">Hotovo (Nahráno)</th>
                        <th className="p-3 text-right font-semibold text-orange-600">Chybovost (GIS Úpravy)</th>
                        <th className="p-3 text-left font-semibold w-1/3">Podíl chybovosti</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                     {activeCenters.map(center => {
                         const stats = statusCounts[center] || { total: 0, uploaded: 0, gisIssues: 0 };
                         if (stats.total === 0) return null;

                         const pctGisIssues = (stats.gisIssues / stats.total) * 100;
                         const pctUploaded = (stats.uploaded / stats.total) * 100;

                         return (
                             <tr key={center} className="hover:bg-slate-50">
                                 <td className="p-3 font-medium text-slate-700">{center}</td>
                                 <td className="p-3 text-right text-slate-600 font-medium">
                                     {stats.total}
                                 </td>
                                 <td className="p-3 text-right font-medium text-emerald-600">
                                     {stats.uploaded} <span className="text-xs text-slate-400">({pctUploaded.toFixed(0)}%)</span>
                                 </td>
                                 <td className="p-3 text-right font-bold text-orange-700">
                                     {stats.gisIssues}
                                 </td>
                                 <td className="p-3">
                                     <div className="flex items-center gap-2">
                                        <div className="flex-1 h-3 rounded-full overflow-hidden bg-slate-100">
                                            <div className="bg-orange-500 h-full" style={{ width: `${pctGisIssues}%` }} title="Chybovost" />
                                        </div>
                                        <span className="text-xs font-bold text-orange-600 w-10 text-right">{pctGisIssues.toFixed(1)}%</span>
                                     </div>
                                 </td>
                             </tr>
                         );
                     })}
                </tbody>
             </table>
        </div>
       </div>

      {/* 3. SECTION: Monthly Matrix (Only if looking at all months) */}
      {monthFilter === 'all' && (
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 overflow-hidden">
         <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
            <TrendingUp className="mr-2 text-blue-600" size={20} />
            Měsíční detail (Metráž)
        </h3>

        <div className="overflow-x-auto">
            <table className="min-w-full text-xs md:text-sm">
                <thead>
                    <tr className="bg-slate-50 text-slate-500">
                        <th className="p-3 text-left font-semibold">Středisko</th>
                        {MONTH_NAMES_SHORT.map(m => (
                            <th key={m} className="p-2 text-right font-semibold w-20">{m}</th>
                        ))}
                        <th className="p-3 text-right font-bold text-slate-700 bg-slate-100">Celkem</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {activeCenters.map(center => {
                         const yearlyTotal = Object.values(data[center]).reduce((a: number, b: number) => a + b, 0);
                         const annualTarget = targets[center] || 0;
                         const monthlyTarget = annualTarget / 12; // Average monthly target

                         return (
                            <tr key={center} className="hover:bg-blue-50/30">
                                <td className="p-3 font-medium text-slate-700">{center}</td>
                                {MONTH_NAMES_SHORT.map((_, idx) => {
                                    const monthNum = idx + 1;
                                    const val = data[center][monthNum];

                                    // Porovnání s měsíčním průměrem (roční cíl / 12)
                                    const metTarget = monthlyTarget > 0 && val >= monthlyTarget;
                                    const closeToTarget = monthlyTarget > 0 && val >= (monthlyTarget * 0.8);

                                    let textColor = "text-slate-400"; // Empty
                                    if (val > 0) textColor = metTarget ? "text-emerald-600 font-bold" : (closeToTarget ? "text-amber-600" : "text-red-600");

                                    return (
                                        <td key={idx} className={`p-2 text-right ${textColor}`}>
                                            {val > 0 ? Number(val / 1000).toFixed(1) + 'k' : '-'}
                                        </td>
                                    );
                                })}
                                <td className="p-3 text-right font-bold text-slate-800 bg-slate-50">
                                    {yearlyTotal.toLocaleString('cs-CZ')}
                                </td>
                            </tr>
                         );
                    })}
                </tbody>
            </table>
        </div>
        <div className="mt-2 text-xs text-slate-400 text-right">
            * Hodnoty v tabulce jsou v tisících metrů (k). Zelená = Splněn měsíční průměr (roční cíl / 12).
        </div>
      </div>
      )}
    </div>
  );
};

export enum RowStatus {
  NEW = 'NEW',
  UPLOADED = 'UPLOADED',
  REVISION = 'REVISION',
  UNUSABLE = 'UNUSABLE'
}

export interface TableRow {
  values: string[];
  status?: RowStatus;
  requiresGisFix?: boolean; // NOVÉ: Příznak, že data vyžadovala úpravu v GIS (nezávislé na stavu)
}

export interface ExtractedData {
  title: string;
  summary: string;
  date: string;
  category: string;
  center: string;
  tags: string[];
  tableHeaders: string[];
  tableRows: TableRow[];
}

export interface DocumentRecord {
  id: string;
  fileName: string;
  uploadDate: string;
  data: ExtractedData;
  rawBase64?: string;
}

export enum AppView {
  DASHBOARD = 'DASHBOARD',
  UPLOAD = 'UPLOAD',
  DETAIL = 'DETAIL'
}

// Mapování: Rok -> { Název střediska -> ROČNÍ cíl v metrech }
export interface AnnualTargets {
  [year: string]: {
    [centerName: string]: number;
  };
}

import React, { useState, useEffect } from 'react';
import { DocumentRecord, AppView, RowStatus, AnnualTargets } from './types';
import { Dashboard } from './components/Dashboard';
import { Scanner } from './components/Scanner';
import { DetailView } from './components/DetailView';
import { Database, Plus } from 'lucide-react';

const STORAGE_KEY = 'pdf-db-documents';
const TARGETS_KEY = 'pdf-db-targets';

const App: React.FC = () => {
  const [documents, setDocuments] = useState<DocumentRecord[]>([]);
  const [targets, setTargets] = useState<AnnualTargets>({});
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [selectedDocId, setSelectedDocId] = useState<string | null>(null);

  // Load documents
  useEffect(() => {
    const storedDocs = localStorage.getItem(STORAGE_KEY);
    if (storedDocs) {
      try {
        setDocuments(JSON.parse(storedDocs));
      } catch (e) {
        console.error("Failed to parse stored documents", e);
      }
    }

    // Load targets
    const storedTargets = localStorage.getItem(TARGETS_KEY);
    if (storedTargets) {
      try {
        const parsed = JSON.parse(storedTargets);

        // Jednoduchá migrace starého formátu { "Středisko": 1000 } na nový { "2024": { "Středisko": 1000 } }
        // Zjistíme, jestli hodnoty jsou čísla (starý formát)
        const isOldFormat = Object.values(parsed).some(val => typeof val === 'number');

        if (isOldFormat) {
            const currentYear = new Date().getFullYear().toString();
            // @ts-ignore - dočasně ignorujeme typ pro migraci
            setTargets({ [currentYear]: parsed });
        } else {
            setTargets(parsed);
        }
      } catch (e) {
        console.error("Failed to parse stored targets", e);
      }
    }
  }, []);

  // Save documents
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(documents));
  }, [documents]);

  // Save targets
  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const handleScanComplete = (newDoc: DocumentRecord) => {
    setDocuments(prev => [newDoc, ...prev]);
    setView(AppView.DASHBOARD);
  };

  const handleDelete = (id: string) => {
    if (confirm("Opravdu chcete tento dokument smazat z databáze?")) {
      setDocuments(prev => prev.filter(d => d.id !== id));
      if (selectedDocId === id) {
        setView(AppView.DASHBOARD);
        setSelectedDocId(null);
      }
    }
  };

  const handleViewDoc = (doc: DocumentRecord) => {
    setSelectedDocId(doc.id);
    setView(AppView.DETAIL);
  };

  const handleRowStatusChange = (docId: string, rowIndex: number, newStatus: RowStatus) => {
    setDocuments(prevDocs => {
      return prevDocs.map(doc => {
        if (doc.id !== docId) return doc;

        const newDoc = { ...doc };
        newDoc.data = { ...doc.data };
        newDoc.data.tableRows = [...doc.data.tableRows];

        const existingRow = newDoc.data.tableRows[rowIndex];
        newDoc.data.tableRows[rowIndex] = {
            ...existingRow,
            status: newStatus
        };

        return newDoc;
      });
    });
  };

  const handleBulkStatusChange = (items: { docId: string, rowIndex: number }[], newStatus: RowStatus) => {
    setDocuments(prevDocs => {
      return prevDocs.map(doc => {
        // Zjistíme, jestli se tento dokument má updatovat
        const updatesForDoc = items.filter(item => item.docId === doc.id);

        if (updatesForDoc.length === 0) return doc;

        const newDoc = { ...doc };
        newDoc.data = { ...doc.data };
        newDoc.data.tableRows = [...doc.data.tableRows];

        updatesForDoc.forEach(update => {
            if (newDoc.data.tableRows[update.rowIndex]) {
                newDoc.data.tableRows[update.rowIndex] = {
                    ...newDoc.data.tableRows[update.rowIndex],
                    status: newStatus
                };
            }
        });

        return newDoc;
      });
    });
  };

  const handleRowGisFixToggle = (docId: string, rowIndex: number) => {
    setDocuments(prevDocs => {
      return prevDocs.map(doc => {
        if (doc.id !== docId) return doc;

        const newDoc = { ...doc };
        newDoc.data = { ...doc.data };
        newDoc.data.tableRows = [...doc.data.tableRows];

        const existingRow = newDoc.data.tableRows[rowIndex];
        newDoc.data.tableRows[rowIndex] = {
            ...existingRow,
            requiresGisFix: !existingRow.requiresGisFix
        };

        return newDoc;
      });
    });
  };

  const handleTargetsUpdate = (newTargets: AnnualTargets) => {
    setTargets(newTargets);
  };

  const selectedDocument = documents.find(d => d.id === selectedDocId);

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900">
      {/* Navbar */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div 
            className="flex items-center gap-3 cursor-pointer"
            onClick={() => setView(AppView.DASHBOARD)}
          >
            <div className="bg-blue-600 p-2 rounded-lg text-white">
              <Database size={20} />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-600 to-indigo-600">
              PDF Databáze
            </h1>
          </div>

          {view === AppView.DASHBOARD && (
            <button 
              onClick={() => setView(AppView.UPLOAD)}
              className="bg-slate-900 hover:bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center"
            >
              <Plus size={16} className="mr-2" />
              Nahrát PDF
            </button>
          )}
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {view === AppView.DASHBOARD && (
          <Dashboard 
            documents={documents} 
            targets={targets}
            onAddClick={() => setView(AppView.UPLOAD)}
            onDeleteClick={handleDelete}
            onViewClick={handleViewDoc}
            onStatusChange={handleRowStatusChange}
            onBulkStatusChange={handleBulkStatusChange}
            onGisFixToggle={handleRowGisFixToggle}
            onTargetsUpdate={handleTargetsUpdate}
          />
        )}

        {view === AppView.UPLOAD && (
          <Scanner 
            onScanComplete={handleScanComplete} 
            onCancel={() => setView(AppView.DASHBOARD)} 
          />
        )}

        {view === AppView.DETAIL && selectedDocument && (
          <DetailView 
            document={selectedDocument} 
            onBack={() => setView(AppView.DASHBOARD)} 
          />
        )}
      </main>
    </div>
  );
};

